  const box=pEl("div",undefined,"p-care-card"),a=pEl("a",t("pDownloadRecord"),"btn btn-line"),preview=pEl("textarea",content,"p-draft");
  a.href=productState.exportUrl;a.download="surya-saathi-passport.txt";a.id="passport-file";
